{
  "filecontent": null,
  "displayorder": 7,
  "pagetemplateid": "718ed8c8-9407-4620-adf3-832ec188887d",
  "parentpageid": "551cf2a7-4cb2-4424-8af7-3422ddbd968e",
  "partialurl": "Dashboard",
  "isroot": false,
  "rootwebpageid": "1d00d537-b8b2-03ca-8729-3e41d9104352",
  "title": "Dashboard",
  "summary": "<p>This is a sample landing page designed to be a starting point for your website</p>",
  "copy": "<div class="row sectionBlockLayout text-start" style="padding: 0px; display: flex; flex-wrap: wrap; margin: 0px; min-height: auto;">
  <!-- Page Title -->
  <div class="container" style="display: flex; flex-wrap: wrap; width: 100%; padding:0px;margin:0px;padding:0px">
    <div class="col-lg-12 columnBlockLayout" style="min-width: 250px; flex-grow: 1; display: flex; flex-direction: column; padding: 0px;margin:0px;">
      <div class="cmdspp-dashboard-title">Dashboard</div>
    </div>
  </div>

<div class="cmdspp-section" id="cmdspp-application-summary">
    <div class="cmdspp-section-title">Application Summary</div>
   <div class="cmdspp-subsection-title">Choose a required action</div>
    {% include 'cmdspp_CommonTable' %}
    {% include 'cmdspp_popup_modal' %}
  </div>
  <!-- Enrollment Types -->
  {% include 'cmdspp_EnrollmentTypes_pp', pageSubtitle:'Select Enrollment Type', pageDescription:'Choose a provider category to view or register' %}
  <!-- Bottom Panels: Recent Inbox Activity + Quick Actions -->

  <div class="cmdspp-bottom-row">
    <div class="cmdspp-bottom-card">
      <div class="cmdspp-bottom-card-title">Recent Inbox Activity <span id="cmdspp-bottom-card-title-count-span"></span></div>
      <div id="cmdspp-inbox-activity-body" class="cmdspp-bottom-card-empty">
        No recent activity
      </div>
    </div>

    <div class="cmdspp-bottom-card">
      <div class="cmdspp-bottom-card-title">Quick Actions</div>
      <div id="cmdspp-quick-actions-body" class="cmdspp-bottom-card-empty">
        No quick actions available
      </div>
    </div>
  </div>
</div>
{% include 'cmdspp_ToastModal' %}",
  "publishingstateid": "c7294317-419f-4724-8068-a91d5da8d92c",
  "enablerating": false,
  "enabletracking": false,
  "excludefromsearch": false,
  "hiddenfromsitemap": true,
  "sharedpageconfiguration": false,
  "feedbackpolicy": 756150000,
  "customcss": "#mainContent{
    width: calc(100% - 221px);
    position: relative;
    left: 221px;
}
.cmdspp-dashboard-header{
    padding:16px;
    margin:9px
}
.xrm-attribute-value #cmdspp-toast-container {
    width: auto !important;
    display: block !important;
}

.xrm-attribute-value #cmdspp-toast-container .cmdspp-toast {
    display: inline-flex !important;
    width: fit-content !important;
    max-width: 400px;
}

.cmdspp-dashboard-title{
    margin:0;
    color:#274463;
    font-size:36px;
    font-weight:400;
    padding: 10px;
leading-trim: NONE;
line-height: 40px;
letter-spacing: 0px;

}
 .cmdspp-dashboard-title {
        margin: 0;
        color: #274463;
        font-size: 36px;
        font-weight: 400;
        line-height: 40px;
        letter-spacing: 0;
        padding: 24px 24px 24px 24px;
    }

    .cmdspp-section {
        width: 100%;
        background: #FFFFFF;
        border-radius: 12px;
        padding:0px 24px 24px 24px;
        margin: 0px;
        box-sizing: border-box;
    }

    .cmdspp-section-title {
        color: #274463;
        margin-bottom: 16px;
       font-weight: 400;
       font-size: 14px;
       line-height: 20px;
       letter-spacing: 0px;
       margin-bottom:0px
       
    }
     .cmdspp-subsection-title {
        color: #274463;
        margin-bottom: 16px;
       font-weight: 400;
       font-size: 12px;
       line-height: 20px;
       letter-spacing: 0px;
       
    }

    .cmdspp-bottom-row {
        display: flex;
        flex-wrap: wrap;
        gap: 16px;
        width: 100%;
        padding: 0 24px 24px 24px;
        box-sizing: border-box;
    }

    .cmdspp-bottom-card {
        flex: 1 1 320px;
        background: #FFFFFF;
        border: 1px solid #E5E9F0;
        border-radius: 12px;
        padding: 20px;
        box-sizing: border-box;
        min-height: 140px;
        width: 50%;
    }

    .cmdspp-bottom-card-title {
        font-size: 16px;
        font-weight: 600;
        color: #274463;
        margin-bottom: 12px;
    }

    .cmdspp-bottom-card-empty {
        color: #5A7099;
        font-size: 13px;
    }

    .cmdspp-notification-item-dashboard{
        padding: 10px !important;
        border-bottom: none !important;
        height: 52.5px !important;
    }

    .cmdspp-notification-footer-dashboard{
        padding-bottom: 8px !important;
    }

    @media (max-width: 767px) {
        .cmdspp-bottom-row {
            flex-direction: column;
        }
    }",
  "customjavascript": "(function () {
    if (window.cmdsppCurrentRole === "Configuration Administrator") {
        window.location.replace("/form-config");
    }
})();

function cmdsppRenderNotifications() {

    const records = window.cmdsppInboxNotificationData || [];
    const count = window.cmdsppUnreadInboxCount

    if (count > 0) {
        const formattedCount = count.toString().padStart(2, "0");
        $("#cmdspp-bottom-card-title-count-span").text(`(${formattedCount})`);
    }

    const html = records.map(x => `

        <div class="cmdspp-notification-item cmdspp-notification-item-dashboard" data-threadid="${x.threadId}">
            <div class="cmdspp-notification-avatar">
                ${x.senderName.charAt(0)}
            </div>
            <div class="cmdspp-notification-content">
                <div class="cmdspp-notification-sender">
                    <div>${x.emailSubject}</div>
                    ${!x.readInd
            ? '<div class="cmdspp-notification-unread"></div>'
            : ''
        }
                </div>
                <div class="cmdspp-notification-subject">
                    ${x.emailBody}
                </div>
            </div>
            
        </div>
    `).join("");

    $("#cmdspp-inbox-activity-body").html(html + `
     <div class="cmdspp-notification-footer cmdspp-notification-footer-dashboard">
            <a href="/inbox">
                View all messages →
            </a>
      </div>
    `);
}


document.addEventListener("DOMContentLoaded", function () {

    if (window.cmdsppCurrentRole === "Configuration Administrator") {
        window.location.replace("/form-config");
        return;
    }

    const columns = [
        { field: "applicationId", label: "APPLICATION ID" },
        { field: "providerType", label: "PROVIDER TYPE" },
        { field: "status", label: "STATUS" },
        { field: "lastUpdated", label: "LAST UPDATED" },
        { field: "action", label: "ACTION" }
    ];


    function loadDashboard() {

        const summarySection = document.getElementById("cmdspp-application-summary");
        const enrollmentPage = document.querySelector(".cmdspp-enrollment-page");

        if (summarySection) {
            summarySection.style.display = "none";
        }

        if (enrollmentPage) {
            enrollmentPage.style.paddingTop = "0px";
        }

        return webapi.safeAjax({
            type: "GET",
            url:
                "/_api/cmdspp_p_idt_inf_dtls" +
                "?$select=_cmdspp_p_app_id_lkp_value,cmdspp_p_pvd_typ_desc" +
                "&$filter=_cmdspp_p_createdby_user_id_value eq " +
                window.cmdsppUserId,

            contentType: "application/json"
        })
.then(function (idtResponse) {

    const idtRecords = idtResponse.value || [];

    if (!idtRecords.length) {
        if (summarySection) {
            summarySection.style.display = "none";
        }
        return [];
    }

    const applicationIds = idtRecords
        .map(idt => idt["_cmdspp_p_app_id_lkp_value"])
        .filter(Boolean);

    if (!applicationIds.length) {
        return [];
    }

    const idFilter = applicationIds
        .map(id => "cmdspp_p_dtl_tbid eq " + id)
        .join(" or ");

    return webapi.safeAjax({
        type: "GET",
        url:
            "/_api/cmdspp_p_dtl_tbs" +
            "?$select=cmdspp_p_dtl_tbid,cmdspp_p_appln_status,cmdspp_p_pg_num,cmdspp_p_section_num,modifiedon,cmdspp_p_page_nam,_cmdspp_p_enrollment_id_value" +
            "&$filter=(" + idFilter + ") and cmdspp_p_appln_status ne 7" +
            "&$orderby=modifiedon desc",
        contentType: "application/json"
    }).then(function (pdtlResponse) {

        const pdtlMap = {};
        (pdtlResponse.value || []).forEach(function (row) {
            const key = row.cmdspp_p_dtl_tbid;
            if (!pdtlMap[key]) {
                pdtlMap[key] = row;
            }
        });

        return idtRecords.map(function (idt) {

            const applicationId = idt["_cmdspp_p_app_id_lkp_value"];
            const pdtl = pdtlMap[applicationId];

            return {
                applicationId:
                    idt["_cmdspp_p_app_id_lkp_value@OData.Community.Display.V1.FormattedValue"] ||
                    applicationId,
                recordId:
                    pdtl?.["cmdspp_p_dtl_tbid"],
                providerType: idt["cmdspp_p_pvd_typ_desc"] || "",
                pageTitle:
                    pdtl?.["cmdspp_p_page_nam"],
                status:
                    pdtl?.["cmdspp_p_appln_status@OData.Community.Display.V1.FormattedValue"] || "",
                lastUpdated:
                    pdtl?.["modifiedon@OData.Community.Display.V1.FormattedValue"] || "",
                pageNumber:
                    pdtl?.["cmdspp_p_pg_num"] || "",
                sectionNumber:
                    pdtl?.["cmdspp_p_section_num"] || "",
                enrollmentId:
                    pdtl?.["_cmdspp_p_enrollment_id_value"]
            };
        });
    });
})
            .then(function (records) {
                records = (records || []).filter(function (record) {
                return record &&
                record.status &&
                record.status.toLowerCase() !== "cancelled";
                });
               records.sort(function (a, b) {
               return new Date(b.lastUpdated) - new Date(a.lastUpdated);
               });
                if (!records || !records.length) {
                    if (summarySection) {
                        summarySection.style.display = "none";
                    }
                    return;
                }

                if (summarySection) {
                    summarySection.style.display = "block";
                }

                CommonTableTemplate.render(columns, records);
            })
            .catch(function (error) {

                console.error("Dashboard Load Error:", error);

                if (summarySection) {
                    summarySection.style.display = "none";
                }

                cmdsppShowToast("error", "Unable to load applications");
            });
    }

//     CommonTableTemplate.onContinue = function (record) {

//     if (!record) return;

//     window.location.href =
//         "/Enrollment-PP/Enroll-Form/" +
//         "?id=" + encodeURIComponent(record.applicationId) +
//         "&record=" + encodeURIComponent(record.recordId) +
//         "&enrollmentId=" + encodeURIComponent(record.enrollmentId);
// };
CommonTableTemplate.onContinue = function (record) {

    if (!record) return;

    window.location.href =
        "/Enrollment-PP/" + record.pageTitle + "/" +
        "?id=" + encodeURIComponent(record.applicationId) +
        "&record=" + encodeURIComponent(record.recordId) +
        "&enrollmentId=" + encodeURIComponent(record.enrollmentId);
};

    CommonTableTemplate.onCancel = function (applicationId,recId) {

        console.log("Cancel clicked", applicationId);

        if (!applicationId) return;

        openCmdsppModal({
            title: "Cancel Application",
            message: "Are you sure you want to cancel this application? This action cannot be undone.",
            primaryText: "Confirm",
            secondaryText: "Close",

            onConfirm: function () {

                showLoader("");


                cancelApplication(recId);

            }
        });
    };
    if (!window.loaderCounterInitialized) {
    window.loaderCounterInitialized = true;
    window.loaderCounter = 0;

    const originalShowLoader = window.showLoader;
    const originalHideLoader = window.hideLoader;

    window.showLoader = function (message) {
        window.loaderCounter++;

        if (window.loaderCounter === 1) {
            originalShowLoader(message);
        }
    };

    window.hideLoader = function () {
        window.loaderCounter--;

        if (window.loaderCounter <= 0) {
            window.loaderCounter = 0;
            originalHideLoader();
        }
    };
}

   function cancelApplication(recordId) {

    console.log("Cancel Clicked", recordId);

    showLoader("");

    webapi.safeAjax({
        type: "PATCH",
        url: "/_api/cmdspp_p_dtl_tbs(" + recordId + ")",
        contentType: "application/json",
        data: JSON.stringify({
            cmdspp_p_appln_status: 7
        })
    })
    .then(function () {

        return loadDashboard();

    })
    .then(function () {

        hideLoader();

        cmdsppShowToast(
            "success",
            "Application cancelled successfully"
        );

    })
    .catch(function (error) {

        hideLoader();

        cmdsppShowToast(
            "error",
            "Unable to cancel application. Please try again."
        );

        console.error(
            "Error cancelling application:",
            error
        );
    });
}
showLoader("");

loadDashboard()
    .then(function () {
        cmdsppRenderNotifications();
        hideLoader();
    })
    .catch(function (error) {
        console.error(error);
        hideLoader();
    });

});"
}
